// Infinitary queue 12. Generated by Infinitary from one source; a newer Infinitary offers its update as a pull request, so change it there, not by hand.
/** Public approval facts; the app retains the naming pattern itself. */
export const NAMING_DECISION = Object.freeze({ checked: "checked", off: "off" });

/** Compose the saved story's exact summary and footer before its approval is published. */
export function commitMessage(story) {
  const footer = /^BREAKING[ -]CHANGE:[^\r\n]*(?:\r?\n[^\r\n]+)*/m.exec(story.projectText)?.[0];
  return [...story.whatChanged, ...(footer ? [footer.replaceAll("\r\n", "\n")] : [])].join("\n\n");
}

/** Only the trusted approval comment carries exact, literal merge words. */
export function commitEnvelope(head, body, title, policy) {
  if (!policy || !Object.values(NAMING_DECISION).includes(policy.naming))
    throw new Error("An approval needs a checked/off naming result.");
  return `<!-- infinitary-squash:${Buffer.from(JSON.stringify({ head, body, title, requestTitle: policy.requestTitle ?? title, naming: policy.naming, literal: true })).toString("hex")} -->`;
}

/** Read the approved literal body; descriptions and older story formats cannot grant authority. */
export function readCommitEnvelope(comment, head, title) {
  return readCommitApproval(comment, head, title).body;
}

/** Keep request identity separate from the explicitly approved squash words. */
export function readCommitApproval(comment, head, title) {
  const data = decodeEnvelope(comment);
  if (
    !data ||
    !Object.values(NAMING_DECISION).includes(data.naming) ||
    typeof data.title !== "string" ||
    (data.requestTitle !== undefined && typeof data.requestTitle !== "string")
  )
    throw new Error(
      "The queue needs this version's approved naming policy. Queue it again before merging.",
    );
  if (data.head !== head || typeof data.body !== "string")
    throw new Error(
      "The approved merge summary does not cover this version. Queue it again before merging.",
    );
  if ((data.requestTitle ?? data.title) !== title)
    throw new Error(
      "The title changed after the merge was approved. Queue this version again before merging.",
    );
  if (data.literal !== true)
    throw new Error(
      "The queue needs literal approved merge words. Queue this version again before merging.",
    );
  return { title: data.title, body: data.body };
}

/**
 * The approval record the queue writes, with its own key, when a queue label
 * from someone who may merge queues a version: the change's title and
 * description at that moment are its merge words, and no naming rule ran.
 * Each host part trusts records its own key wrote.
 */
export function labelApproval(head, body, title) {
  return `Queued at this version with the infinitary-queue label. A later push leaves the queue; put the label on again to queue that version.\n\n<!-- infinitary-merge-approval -->\n${commitEnvelope(head, body, title, { naming: NAMING_DECISION.off })}`;
}

/** Append-only withdrawal: a status cannot undo this trusted record. */
export function revocationEnvelope(head) {
  return `<!-- infinitary-merge-revocation:${Buffer.from(JSON.stringify({ head })).toString("hex")} -->`;
}

/** Host adapters supply their merge-level permission check; untrusted bytes are never decoded. */
export async function newestTrustedApproval(comments, head, mayMerge) {
  for (const comment of [...comments].sort((a, b) => b.id - a.id)) {
    if (comment.system || typeof comment.body !== "string") continue;
    const revoked = comment.body.includes("<!-- infinitary-merge-revocation:");
    const approved = comment.body.includes("<!-- infinitary-merge-approval -->");
    if ((!revoked && !approved) || !(await mayMerge(comment))) continue;
    const data = decodeEnvelope(
      comment.body,
      revoked ? "infinitary-merge-revocation" : "infinitary-squash",
    );
    if (data?.head === head)
      return {
        id: comment.id,
        kind: revoked ? "revocation" : "approval",
        head,
        body: comment.body,
      };
  }
  return undefined;
}

function decodeEnvelope(description, marker = "infinitary-squash") {
  const found = new RegExp(`<!-- ${marker}:([0-9a-f]+) -->`).exec(description);
  return found ? JSON.parse(Buffer.from(found[1], "hex").toString("utf8")) : undefined;
}
